using System;
using System.IO;
using System.IO.Compression;

namespace NearbyLanToolbox
{
    // 本文件由 tools\embed-assets.ps1 自动生成，请勿手工编辑。
    // 源文件：public\index.html、public\app.js、public\styles.css
    internal static class EmbeddedAssets
    {
        public static readonly byte[] Index = Inflate("");

        public static readonly byte[] App = Inflate("");

        public static readonly byte[] Styles = Inflate("");

        private static byte[] Inflate(string value)
        {
            byte[] compressed = Convert.FromBase64String(value);
            using (MemoryStream input = new MemoryStream(compressed))
            using (GZipStream gzip = new GZipStream(input, CompressionMode.Decompress))
            using (MemoryStream output = new MemoryStream())
            {
                gzip.CopyTo(output);
                return output.ToArray();
            }
        }
    }
}
